using System.IO;using System.Security.Cryptography;using System.Text.Json;
namespace Luma.Authentication;
public interface IAuthSessionStore{AuthSession? Load();void Save(AuthSession s);void Clear();}
public sealed class ProtectedAuthSessionStore:IAuthSessionStore{static readonly byte[] Entropy="Luma.Auth.Session.v1"u8.ToArray();readonly string path=Path.Combine(LumaState.DirectoryPath,"auth-session.dat");readonly object gate=new();public AuthSession? Load(){lock(gate)try{if(!File.Exists(path))return null;var c=ProtectedData.Unprotect(File.ReadAllBytes(path),Entropy,DataProtectionScope.CurrentUser);try{return JsonSerializer.Deserialize<AuthSession>(c);}finally{CryptographicOperations.ZeroMemory(c);}}catch(Exception ex){App.Log(ex);Clear();return null;}}public void Save(AuthSession s){lock(gate){Directory.CreateDirectory(Path.GetDirectoryName(path)!);var c=JsonSerializer.SerializeToUtf8Bytes(s);try{File.WriteAllBytes(path,ProtectedData.Protect(c,Entropy,DataProtectionScope.CurrentUser));}finally{CryptographicOperations.ZeroMemory(c);}}}public void Clear(){lock(gate)try{File.Delete(path);}catch(Exception ex){App.Log(ex);}}}
